import sqlite3; con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
refs={}
for (t,) in con.execute("select name from sqlite_master where type='table'"):
    for f in con.execute(f'PRAGMA foreign_key_list("{t}")'):
        refs.setdefault(f[2],[]).append(f"{t}.{f[3]}")
for k in ['rooms','access_needs','base_taxonomy_identity','base_icf','base_taxonomy_medical','terms','base_parameters','lang_jur_map','access_stakes']:
    print(k, refs.get(k))
print([c[1] for c in con.execute("pragma table_info(specifications)")])
print(con.execute("select count(*) from access_needs where need_code in (select need_code from access_need_icf)").fetchone())
empty = {t for (t,) in con.execute("select name from sqlite_master where type='table'") if con.execute(f'select count(*) from "{t}"').fetchone()[0] == 0}
for (t,) in con.execute("select name from sqlite_master where type='table'"):
    dead = {f[3] for f in con.execute(f'PRAGMA foreign_key_list("{t}")') if f[2] in empty}
    for c in con.execute(f'PRAGMA table_info("{t}")'):
        if c[1] in dead and c[3]: print(f"UNWRITABLE  {t}.{c[1]} -> empty table")
PY
